import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int a = scanner.nextInt();
        int ta = scanner.nextInt();

        int b = scanner.nextInt();
        int tb = scanner.nextInt();

        String timeStr = scanner.next();

        // Parse time hh:mm
        int hours = Integer.parseInt(timeStr.substring(0, 2));
        int minutes = Integer.parseInt(timeStr.substring(3, 5));
        int simionDeparture = hours * 60 + minutes;
        int simionArrival = simionDeparture + ta;

        int count = 0;

        // Buses from B depart every 'b' minutes starting from 05:00 (300 minutes)
        // The first bus from B departs at 05:00.
        // We need to find all buses from B that Simion meets on the way.
        // Simion is on the road from time simionDeparture to simionArrival.
        // A bus from B departs at time t. It arrives at A at time t + tb.
        // Simion meets this bus if:
        // 1. The bus is on the road when Simion is on the road.
        // 2. Specifically, the bus must have departed before Simion arrives at B (otherwise they wouldn't meet on the road, or meet at B which is excluded).
        //    Actually, let's look at the condition for meeting on the road (strictly between A and B).
        //    
        // Let's analyze the meeting condition more carefully.
        // Simion's position at time T (where T is in [simionDeparture, simionArrival]) is proportional to (T - simionDeparture) / ta.
        // Bus from B departs at time t. Its position at time T (where T is in [t, t + tb]) is proportional to (T - t) / tb (distance from B).
        // They meet when their positions are equal.
        // Distance from A for Simion: d_s = (T - simionDeparture) * (1/ta) * TotalDistance
        // Distance from A for Bus: d_b = TotalDistance - (T - t) * (1/ta) * TotalDistance ... wait.
        // Let's use simpler logic.
        // Simion moves from A to B. Bus moves from B to A.
        // They meet if the bus departed before Simion arrived at B, AND the bus arrives at A after Simion departed from A.
        // If the bus departs at t:
        // - If t >= simionArrival, the bus departs after Simion has already arrived at B. No meeting on the road.
        // - If t + tb <= simionDeparture, the bus arrives at A before Simion departs. No meeting on the road.
        // - If t < simionArrival and t + tb > simionDeparture, they meet.
        //   But we must exclude meetings at the start (A) and finish (B).
        //   Meeting at A: This happens if the bus arrives at A exactly when Simion departs. i.e., t + tb == simionDeparture.
        //   Meeting at B: This happens if the bus departs exactly when Simion arrives at B. i.e., t == simionArrival.
        //   
        // So the condition for counting a bus is:
        // t < simionArrival  AND  t + tb > simionDeparture
        // AND t != simionArrival (already covered by <)
        // AND t + tb != simionDeparture
        //
        // Let's verify with the example.
        // a=10, ta=30. b=10, tb=35.
        // Simion departs 05:20 (320 min). Arrives 05:50 (350 min).
        // Buses from B depart at 05:00 (300), 05:10 (310), 05:20 (320), 05:30 (330), 05:40 (340), 05:50 (350)...
        // 
        // Bus 1: t=300. t < 350 (True). t+tb = 300+35=335. 335 > 320 (True). Count.
        // Bus 2: t=310. t < 350 (True). t+tb = 310+35=345. 345 > 320 (True). Count.
        // Bus 3: t=320. t < 350 (True). t+tb = 320+35=355. 355 > 320 (True). Count.
        // Bus 4: t=330. t < 350 (True). t+tb = 330+35=365. 365 > 320 (True). Count.
        // Bus 5: t=340. t < 350 (True). t+tb = 340+35=375. 375 > 320 (True). Count.
        // Bus 6: t=350. t < 350 (False). Stop.
        // Total count = 5. Matches sample output.
        //
        // What if t + tb == simionDeparture?
        // Example: Simion departs 320. Bus departs 285, tb=35. 285+35=320.
        // Condition: t < simionArrival (285 < 350 True). t+tb > simionDeparture (320 > 320 False).
        // So it is not counted. This is correct because they meet at A (start).
        //
        // What if t == simionArrival?
        // Example: Simion arrives 350. Bus departs 350.
        // Condition: t < simionArrival (350 < 350 False).
        // So it is not counted. This is correct because they meet at B (finish).

        // Buses depart from B at 05:00, 05:00+b, 05:00+2b, ...
        // 05:00 is 5 * 60 = 300 minutes.
        // We iterate through possible departure times t.
        // t starts at 300.
        // We stop when t >= simionArrival.

        int startB = 5 * 60; // 05:00
        for (int t = startB; t < simionArrival; t += b) {
            if (t + tb > simionDeparture) {
                count++;
            }
        }

        System.out.println(count);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read input
        int a = scanner.nextInt();
        int ta = scanner.nextInt();
        int b = scanner.nextInt();
        int tb = scanner.nextInt();
        String timeStr = scanner.next();

        // Parse departure time
        int hours = Integer.parseInt(timeStr.substring(0, 2));
        int minutes = Integer.parseInt(timeStr.substring(3, 5));
        int simionDeparture = hours * 60 + minutes;
        int simionArrival = simionDeparture + ta;

        // Buses from B to A depart at times: 0, b, 2b, ...
        // A bus departing from B at time tB will be on the road during the interval [tB, tB + tb].
        // Simion is on the road during the interval (simionDeparture, simionArrival).
        // They meet if the intervals overlap, excluding the endpoints.
        // Overlap condition: tB < simionArrival AND tB + tb > simionDeparture
        // This simplifies to: tB > simionDeparture - tb AND tB < simionArrival

        // Buses run from 05:00 (300 minutes) to 11:59 PM (23*60+59 = 1439 minutes).
        // The problem states "the last one departs not later than at 11:59 PM".
        // So valid departure times tB are in [300, 1439].

        int count = 0;

        // Iterate through all possible departure times for buses from B
        // Start from the earliest possible departure (300)
        // We can optimize by starting from the first valid tB that could potentially meet Simion.
        // tB must be > simionDeparture - tb
        // And tB must be < simionArrival
        // And tB must be in [300, 1439]

        int minTB = 300; // 05:00
        int maxTB = 23 * 60 + 59; // 23:59

        // Find the first multiple of b that is >= minTB
        // Actually, we just need to iterate through multiples of b.
        // Let's find the range of k such that tB = k*b is in [minTB, maxTB]

        // To be safe and simple, we can iterate from the smallest possible tB that is a multiple of b
        // and is >= minTB, up to maxTB.

        // Calculate the first k such that k*b >= minTB
        int startK = (minTB + b - 1) / b;
        // Calculate the last k such that k*b <= maxTB
        int endK = maxTB / b;

        for (int k = startK; k <= endK; k++) {
            int tB = k * b;

            // Check if this bus meets Simion
            // Condition: tB < simionArrival AND tB + tb > simionDeparture
            if (tB < simionArrival && tB + tb > simionDeparture) {
                count++;
            }
        }

        System.out.println(count);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read input
        int a = scanner.nextInt();
        int ta = scanner.nextInt();
        int b = scanner.nextInt();
        int tb = scanner.nextInt();
        String timeStr = scanner.next();

        // Parse departure time
        int hours = Integer.parseInt(timeStr.substring(0, 2));
        int minutes = Integer.parseInt(timeStr.substring(3, 5));
        int simionStart = hours * 60 + minutes;
        int simionEnd = simionStart + ta;

        int count = 0;

        // Buses from B to A depart every b minutes starting from 05:00 (300 minutes)
        // The last bus departs not later than 23:59 (1439 minutes)
        int startHour = 5;
        int endHour = 23;
        int firstDeparture = startHour * 60; // 300
        int lastDeparture = endHour * 60 + 59; // 1439

        // Iterate through all possible departure times of buses from B
        for (int depTime = firstDeparture; depTime <= lastDeparture; depTime += b) {
            // A bus from B departs at depTime and arrives at depTime + tb
            // Simion is on the road from simionStart to simionEnd
            // They meet if the bus is on the road when Simion is on the road
            // Bus is on road: [depTime, depTime + tb]
            // Simion is on road: [simionStart, simionEnd]

            // They meet if the intervals overlap.
            // However, we must exclude meetings at the start (city A) and finish (city B).
            // Meeting at start (city A) happens if the bus arrives at city A exactly when Simion starts.
            // Bus arrives at city A at depTime + tb.
            // If depTime + tb == simionStart, they meet at city A. Exclude.

            // Meeting at finish (city B) happens if the bus departs from city B exactly when Simion arrives.
            // Bus departs at depTime.
            // If depTime == simionEnd, they meet at city B. Exclude.

            // Condition for meeting on the way:
            // The bus must have departed before Simion arrives (depTime < simionEnd)
            // AND the bus must arrive after Simion starts (depTime + tb > simionStart)

            if (depTime < simionEnd && depTime + tb > simionStart) {
                // Check exclusions
                if (depTime + tb == simionStart) {
                    // Meet at city A
                    continue;
                }
                if (depTime == simionEnd) {
                    // Meet at city B
                    continue;
                }
                count++;
            }
        }

        System.out.println(count);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int a = scanner.nextInt();
        int ta = scanner.nextInt();

        int b = scanner.nextInt();
        int tb = scanner.nextInt();

        String timeStr = scanner.next();

        int hour = Integer.parseInt(timeStr.substring(0, 2));
        int minute = Integer.parseInt(timeStr.substring(3, 5));

