            // Calculate the meeting time T
            // T = (ta * tb + tb * simionDeparture - ta * t_dep) / (ta + tb)
            // To avoid floating point issues, we can use inequalities.
            // We want: simionDeparture < T < simionArrival

            // T > simionDeparture
            // (ta * tb + tb * simionDeparture - ta * t_dep) / (ta + tb) > simionDeparture
            // ta * tb + tb * simionDeparture - ta * t_dep > simionDeparture * (ta + tb)
            // ta * tb + tb * simionDeparture - ta * t_dep > simionDeparture * ta + simionDeparture * tb
            // ta * tb - ta * t_dep > simionDeparture * ta
            // tb - t_dep > simionDeparture
            // t_dep < tb - simionDeparture

            // T < simionArrival
            // (ta * tb + tb * simionDeparture - ta * t_dep) / (ta + tb) < simionArrival
            // ta * tb + tb * simionDeparture - ta * t_dep < simionArrival * (ta + tb)
            // ta * tb + tb * simionDeparture - ta * t_dep < (simionDeparture + ta) * (ta + tb)
            // ta * tb + tb * simionDeparture - ta * t_dep < simionDeparture * ta + simionDeparture * tb + ta^2 + ta * tb
            // - ta * t_dep < simionDeparture * ta + ta^2
            // - t_dep < simionDeparture + ta
            // t_dep > - (simionDeparture + ta)
            // Since t_dep >= 0, this is always true if simionDeparture + ta >= 0, which it is.
            // Wait, let's re-verify the second inequality.

            // Let's re-derive carefully.
            // T = (ta * tb + tb * simionDeparture - ta * t_dep) / (ta + tb)

            // Condition 1: T > simionDeparture
            // ta * tb + tb * simionDeparture - ta * t_dep > simionDeparture * (ta + tb)
            // ta * tb + tb * simionDeparture - ta * t_dep > simionDeparture * ta + simionDeparture * tb
            // ta * tb - ta * t_dep > simionDeparture * ta
            // Divide by ta (positive):
            // tb - t_dep > simionDeparture
            // t_dep < tb - simionDeparture

            // Condition 2: T < simionArrival
            // ta * tb + tb * simionDeparture - ta * t_dep < simionArrival * (ta + tb)
            // simionArrival = simionDeparture + ta
            // ta * tb + tb * simionDeparture - ta * t_dep < (simionDeparture + ta) * (ta + tb)
            // ta * tb + tb * simionDeparture - ta * t_dep < simionDeparture * ta + simionDeparture * tb + ta^2 + ta * tb
            // Subtract ta * tb from both sides:
            // tb * simionDeparture - ta * t_dep < simionDeparture * ta + simionDeparture * tb + ta^2
