        // (time - simionDeparture) / ta = 1 - (time - t) / tb
        // (time - simionDeparture) / ta + (time - t) / tb = 1
        // Let's solve for time:
        // tb * (time - simionDeparture) + ta * (time - t) = ta * tb
        // tb * time - tb * simionDeparture + ta * time - ta * t = ta * tb
        // time * (ta + tb) = ta * tb + tb * simionDeparture + ta * t
