        // t must satisfy: t > simionDeparture - tb AND t < simionArrival
        // Also t must be a valid departure time: t >= firstBusB and t <= lastBusB
        // And t must be of the form: firstBusB + k * b for some non-negative integer k

        // Lower bound for t: t > simionDeparture - tb, so t >= simionDeparture - tb + 1 (since t is integer)
        // But also t >= firstBusB
        int lowerBound = Math.max(firstBusB, simionDeparture - tb + 1);

        // Upper bound for t: t < simionArrival, so t <= simionArrival - 1
        // But also t <= lastBusB
        int upperBound = Math.min(lastBusB, simionArrival - 1);

        if (lowerBound > upperBound) {
