        }

        // Find the largest k such that firstBusB + k * b <= upperBound
        int kMax = 0;
        if (upperBound >= firstBusB) {
            kMax = (upperBound - firstBusB) / b; // floor division
        }

        if (kMin <= kMax) {
            count = kMax - kMin + 1;
        }

        System.out.println(count);
    }
